import math

def _num(v, default):
    return default if v is None else float(v)


def _last(vals):
    for v in reversed(vals):
        if v is not None:
            return float(v)
    return None


def _features(history):
    t0 = history[0].get('time_min')
    t1 = history[-1].get('time_min')
    if t0 is None or t1 is None:
        el = float(len(history) - 1)
    else:
        el = max(0.0, float(t1) - float(t0))
    ws = [float(h['watts']) for h in history if h.get('watts') is not None]
    wmean = sum(ws) / len(ws) if ws else 150.0
    wnow = ws[-1] if ws else 150.0
    w0 = ws[0] if ws else 150.0
    cur = history[-1]
    mass = _num(cur.get('mass'), 72.0)
    height = _num(cur.get('height'), 173.0)
    age = _num(cur.get('age'), 30.0)
    if mass <= 0: mass = 72.0
    if height <= 0: height = 173.0
    bmi = mass / ((height / 100.0) ** 2)
    hrs = [float(h['hr']) for h in history if h.get('hr') is not None]
    sk = [float(h['skin_temp']) for h in history if h.get('skin_temp') is not None]
    hr5 = sum(hrs[-5:]) / len(hrs[-5:]) if hrs else 150.0
    hr_d = (sum(hrs[-3:]) / len(hrs[-3:]) - hrs[0]) if len(hrs) > 1 else 0.0
    skin_now = sk[-1] if sk else 34.5
    skin_first = sk[0] if sk else 34.5
    skin5 = sum(sk[-5:]) / len(sk[-5:]) if sk else 34.5
    return {'el': el, 'sqrtel': math.sqrt(el), 'logel': math.log1p(el), 'wmean': wmean, 'wnow': wnow, 'w0': w0,
            'bmi': bmi, 'bmi_el': bmi * el / 10.0, 'age': age, 'mass': mass, 'height': height,
            'hr5': hr5, 'hr_d': hr_d, 'skin_now': skin_now, 'skin_first': skin_first, 'skin5': skin5,
            'wmean_m': wmean / mass, 'wm_el': wmean * el / 1000.0, 'mass_el': mass * el / 100.0, 'age_el': age * el / 100.0}
