def M(cols): return np.array([[r[1][c] for c in cols] for r in ROWS])
def fit(cols, rows_mask=None, kind='huber', alpha=1.0, eps=1.2):
    A=M(cols); 
    if rows_mask is not None: A=A[rows_mask]; yy=y[rows_mask]
    else: yy=y
    mu=A.mean(0); sd=A.std(0)+1e-9
    m=(HuberRegressor(alpha=alpha,epsilon=eps,max_iter=2000) if kind=='huber' else Ridge(alpha=alpha)).fit((A-mu)/sd,yy)
